func (client containerAllocationHTTPClient) Do(request *http.Request) (*http.Response, error) {
	cloned := request.Clone(request.Context())
	cloned.URL = request.URL.Clone()
	cloned.URL.Scheme = "http"
	cloned.URL.Host = strings.TrimPrefix(client.server.URL, "http://")
	return client.server.Client().Do(cloned)
}

func currentContainerAllocations(ctx context.Context, factory *ociclient.Factory, bundle release.ContainerBundle, roots trust.Keyring, target release.ContainerTarget) (release.SequenceLocation, error) {
	if ctx == nil || factory == nil {
		return release.SequenceLocation{}, errors.New("container allocation requires context and OCI credentials")
	}
	if err := ctx.Err(); err != nil {
		return release.SequenceLocation{}, err
	}
	envelope, err := trust.DecodeEnvelope(bundle.Migration)
	if err != nil {
		return release.SequenceLocation{}, err
	}
	// Established migrations retain authority after their submission envelope expires.
	migration, err := release.VerifySequenceMigrationHistorical(envelope, roots, target.Role, target.Environment)
	if err != nil {
		return release.SequenceLocation{}, err
	}
	entry, ok := catalog.Lookup(migration.Region)
	if !ok {
		return release.SequenceLocation{}, errors.New("container allocation migration has no OCI region")
	}
	regional, err := factory.ForRegion(entry.OCIRegion)
	if err != nil {
		return release.SequenceLocation{}, err
	}
	client, err := regional.ObjectStorage()
	if err != nil {
		return release.SequenceLocation{}, err
	}
	return release.SequenceLocation{Client: containerAllocationReader{client: client}, Namespace: migration.Namespace, Bucket: migration.Bucket}, nil
}

type containerAllocationReader struct {
	client objectstorage.ObjectStorageClient
}

func (reader containerAllocationReader) GetObject(ctx context.Context, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	return reader.client.GetObject(ctx, request)
}

func (containerAllocationReader) PutObject(context.Context, objectstorage.PutObjectRequest) (objectstorage.PutObjectResponse, error) {
	return objectstorage.PutObjectResponse{}, errors.New("runtime container allocation verification cannot write release sequences")
}

// ForRegion preserves this factory's authentication and retry policy while
// selecting another catalog region, including the tenancy's home region.
func (f *Factory) ForRegion(region string) (*Factory, error) {
	if !catalog.IsOCIRegion(region) {
		return nil, fmt.Errorf("OCI region %q is not in the region catalog", region)
	}
	if f.origin != nil {
		return f.origin.ForRegion(region)
	}
	if region == f.region {
		return f, nil
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if sibling := f.regions[region]; sibling != nil {
		return sibling, nil
	}
	if f.regions == nil {
		f.regions = map[string]*Factory{}
	}
	sibling := &Factory{provider: f.provider, region: region, limits: f.limits,
		policy: f.policy, limiters: map[Service]*rate.Limiter{}, origin: f}
	f.regions[region] = sibling
	return sibling, nil
}

func (f *Factory) ObjectStorage() (objectstorage.ObjectStorageClient, error) {
	client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI Object Storage client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceObjectStorage)
	client.HTTPClient = Instrument(client.HTTPClient, string(ServiceObjectStorage))
	return client, nil
}

func (client ObjectStorageClient) GetObject(ctx context.Context, request GetObjectRequest) (response GetObjectResponse, err error) {
	var ociResponse common.OCIResponse
	policy := common.DefaultRetryPolicy()
	if client.RetryPolicy() != nil {
		policy = *client.RetryPolicy()
	}
	if request.RetryPolicy() != nil {
		policy = *request.RetryPolicy()
	}
	ociResponse, err = common.Retry(ctx, request, client.getObject, policy)
	if err != nil {
		if ociResponse != nil {
			if httpResponse := ociResponse.HTTPResponse(); httpResponse != nil {
				opcRequestId := httpResponse.Header.Get("opc-request-id")
				response = GetObjectResponse{RawResponse: httpResponse, OpcRequestId: &opcRequestId}
			} else {
				response = GetObjectResponse{}
			}
		}
		return
	}
	if convertedResponse, ok := ociResponse.(GetObjectResponse); ok {
		response = convertedResponse
	} else {
		err = fmt.Errorf("failed to convert OCIResponse into GetObjectResponse")
	}
	return
}

// getObject implements the OCIOperation interface (enables retrying operations)
func (client ObjectStorageClient) getObject(ctx context.Context, request common.OCIRequest, binaryReqBody *common.OCIReadSeekCloser, extraHeaders map[string]string) (common.OCIResponse, error) {

	httpRequest, err := request.HTTPRequest(http.MethodGet, "/n/{namespaceName}/b/{bucketName}/o/{objectName}", binaryReqBody, extraHeaders)
	if err != nil {
		return nil, err
	}

	host := client.Host
	request.(GetObjectRequest).ReplaceMandatoryParamInPath(&client.BaseClient, client.requiredParamsInEndpoint)
	common.UpdateEndpointTemplateForOptions(&client.BaseClient)
	common.SetMissingTemplateParams(&client.BaseClient)
	defer func() {
		client.Host = host
	}()

	var response GetObjectResponse
	var httpResponse *http.Response
	httpResponse, err = client.CallWithServiceAndOperationName(ctx, &httpRequest, "objectStorage", "GetObject")
	response.RawResponse = httpResponse
	if err != nil {
		apiReferenceLink := "https://docs.oracle.com/iaas/api/#/en/objectstorage/20160918/Object/GetObject"
		err = common.PostProcessServiceError(err, "ObjectStorage", "GetObject", apiReferenceLink)
		return response, err
	}

	err = common.UnmarshalResponse(httpResponse, &response)

