// The real upstream control API rejects mutable Config.Data. Only the lost
// service-update response is injected; version checks and stores are real.
type materialControlClient struct {
	api.ControlClient
	server     *controlapi.Server
	failUpdate bool
	updates    int
}

func (client *materialControlClient) ListConfigs(ctx context.Context, request *api.ListConfigsRequest, _ ...grpc.CallOption) (*api.ListConfigsResponse, error) {
	return client.server.ListConfigs(ctx, request)
}
func (client *materialControlClient) CreateConfig(ctx context.Context, request *api.CreateConfigRequest, _ ...grpc.CallOption) (*api.CreateConfigResponse, error) {
	return client.server.CreateConfig(ctx, request)
}
func (client *materialControlClient) UpdateConfig(ctx context.Context, request *api.UpdateConfigRequest, _ ...grpc.CallOption) (*api.UpdateConfigResponse, error) {
	return client.server.UpdateConfig(ctx, request)
}
func (client *materialControlClient) UpdateService(ctx context.Context, request *api.UpdateServiceRequest, _ ...grpc.CallOption) (*api.UpdateServiceResponse, error) {
	client.updates++
	if client.failUpdate {
		client.failUpdate = false
		return nil, errors.New("manager unavailable after metadata reservation")
	}
	return client.server.UpdateService(ctx, request)
}

type materialFence struct{}

func (materialFence) Current() authority.Snapshot         { return authority.Snapshot{Epoch: 1} }
func (materialFence) Guard(context.Context, uint64) error { return nil }

func encodeContainerSnapshot(snapshot containerSecretSnapshot) ([]byte, error) {
	wire, err := protocol.EncodeJSON(snapshot)
	if err != nil {
		return nil, err
	}
	if len(wire) > 32<<10 {
		return nil, containermaterial.ErrPending
	}
	return wire, nil
}

func containerSnapshotName(serviceID string) string {
	digest := sha256.Sum256([]byte(serviceID))
	return "ts-container-material-" + hex.EncodeToString(digest[:16])
}

func lookupContainerSnapshot(ctx context.Context, client api.ControlReader, serviceID string) (*api.Config, error) {
	name := containerSnapshotName(serviceID)
	listed, err := client.ListConfigs(ctx, &api.ListConfigsRequest{Filters: &api.ListConfigsRequest_Filters{Names: []string{name}}})
	if err != nil {
		return nil, err
	}
	if len(listed.Configs) == 0 {
		return nil, nil
	}
	if len(listed.Configs) != 1 || listed.Configs[0] == nil || listed.Configs[0].Spec.Annotations.Name != name {
		return nil, containermaterial.ErrPending
	}
	return listed.Configs[0], nil
}

func checkContainerSnapshot(ctx context.Context, client api.ControlReader, wanted containerSecretSnapshot) error {
	config, err := lookupContainerSnapshot(ctx, client, wanted.ServiceID)
	if err != nil {
		return err
	}
	if config == nil {
		return containermaterial.ErrPending
	}
	wire, err := encodeContainerSnapshot(wanted)
	if err != nil {
		return err
	}
	if string(config.Spec.Data) != containerSecretSnapshotSchema || config.Spec.Annotations.Labels[containerSecretSnapshotLabel] != string(wire) {
		return containermaterial.ErrPending
	}
	return nil
}

// syncContainerSnapshot writes version metadata before advancing the upstream counter.
// A lost response resumes from that config; there is no parallel task lifecycle.
func syncContainerSnapshot(ctx context.Context, client api.ControlClient, fence authority.Fencer, service *api.Service, next containerSecretSnapshot) error {
	config, err := lookupContainerSnapshot(ctx, client, next.ServiceID)
	if err != nil {
		return err
	}
	epoch := fence.Current().Epoch
	if config == nil {
		wire, err := encodeContainerSnapshot(next)
		if err != nil {
			return err
		}
		if err := fence.Guard(ctx, epoch); err != nil {
			return err
		}
		_, err = client.CreateConfig(ctx, &api.CreateConfigRequest{Spec: &api.ConfigSpec{Annotations: api.Annotations{Name: containerSnapshotName(next.ServiceID), Labels: map[string]string{containerSecretSnapshotLabel: string(wire)}}, Data: []byte(containerSecretSnapshotSchema)}})
		return err
	}
	var previous containerSecretSnapshot
	if string(config.Spec.Data) != containerSecretSnapshotSchema {
		return containermaterial.ErrPending
	}
	if err := protocol.DecodeStrict([]byte(config.Spec.Annotations.Labels[containerSecretSnapshotLabel]), &previous, 32<<10); err != nil {
		return err
	}
	if previous.ServiceID != next.ServiceID {
		return containermaterial.ErrPending
	}
	changed := previous.ConfigDigest != next.ConfigDigest
	newOperation := previous.OperationID != next.OperationID
	for key, value := range next.Versions {
		old, exists := previous.Versions[key]
		if exists && old.ID == value.ID && value.Version < old.Version {
			return containermaterial.ErrPending
		}
		if !exists || old != value {
			changed = true
		}
	}
	if len(previous.Versions) != len(next.Versions) {
		changed = true
	}
	if newOperation {
		wire, err := encodeContainerSnapshot(next)
		if err != nil {
			return err
		}
		spec := config.Spec.Copy()
		spec.Annotations.Labels[containerSecretSnapshotLabel] = string(wire)
		if err := fence.Guard(ctx, epoch); err != nil {
			return err
		}
		_, err = client.UpdateConfig(ctx, &api.UpdateConfigRequest{ConfigID: config.ID, ConfigVersion: &config.Meta.Version, Spec: spec})
		return err
	}
	if previous.Generation > next.Generation {
		if previous.Generation != next.Generation+1 {
			return containermaterial.ErrPending
		}
		// Finish the reserved generation before observing a newer Vault version.
		next = previous
	} else if changed {
		if previous.Generation != next.Generation || next.Generation == ^uint64(0) {
			return containermaterial.ErrPending
		}
		next.Generation++
		wire, err := encodeContainerSnapshot(next)
		if err != nil {
			return err
		}
		spec := config.Spec.Copy()
		spec.Annotations.Labels[containerSecretSnapshotLabel] = string(wire)
		if err := fence.Guard(ctx, epoch); err != nil {
			return err
		}
		if _, err := client.UpdateConfig(ctx, &api.UpdateConfigRequest{ConfigID: config.ID, ConfigVersion: &config.Meta.Version, Spec: spec}); err != nil {
			return err
		}
	} else if previous.Generation != next.Generation {
		return containermaterial.ErrPending
	}
	if next.Generation == service.Spec.Task.ForceUpdate {
		return nil
	}
	spec := service.Spec.Copy()
	spec.Task.ForceUpdate = next.Generation
	if err := fence.Guard(ctx, epoch); err != nil {
		return err
	}
	if _, err := client.UpdateService(ctx, &api.UpdateServiceRequest{ServiceID: service.ID, ServiceVersion: &service.Meta.Version, Spec: spec}); err != nil {
		return err
	}
	return fmt.Errorf("%w: OCI Vault versions replaced upstream task generation", containermaterial.ErrPending)
}

type Server struct {
	store          *store.MemoryStore
	raft           *raft.Node
	securityConfig *ca.SecurityConfig
	netvalidator   networkallocator.DriverValidator
	dr             *drivers.DriverProvider

	// NetworkHooks intercept and mutate API server responses for GetNetwork
	// and ListNetworks API requests when set.
	NetworkHooks NetworkViewResponseMutator
}

// NewServer creates a Cluster API server.
func NewServer(store *store.MemoryStore, raft *raft.Node, securityConfig *ca.SecurityConfig, nv networkallocator.DriverValidator, dr *drivers.DriverProvider) *Server {
	if nv == nil {
		nv = networkallocator.InertProvider{}
	}
	return &Server{
		store:          store,
		dr:             dr,
		raft:           raft,
		securityConfig: securityConfig,
		netvalidator:   nv,
	}
}

func (s *Server) UpdateConfig(ctx context.Context, request *api.UpdateConfigRequest) (*api.UpdateConfigResponse, error) {
	if request.ConfigID == "" || request.ConfigVersion == nil {
		return nil, status.Error(codes.InvalidArgument, errInvalidArgument.Error())
	}

	var config *api.Config
	err := s.store.Update(func(tx store.Tx) error {
		config = store.GetConfig(tx, request.ConfigID)
		if config == nil {
			return status.Errorf(codes.NotFound, "config %s not found", request.ConfigID)
		}

		// Check if the Name is different than the current name, or the config is non-nil and different
		// than the current config
		if config.Spec.Annotations.Name != request.Spec.Annotations.Name ||
			(request.Spec.Data != nil && !bytes.Equal(request.Spec.Data, config.Spec.Data)) {
			return status.Errorf(codes.InvalidArgument, "only updates to Labels are allowed")
		}

		// We only allow updating Labels
		config.Meta.Version = *request.ConfigVersion
		config.Spec.Annotations.Labels = request.Spec.Annotations.Labels

		return store.UpdateConfig(tx, config)
	})
	if err != nil {
		return nil, err
	}

	log.G(ctx).WithFields(log.Fields{
		"config.ID":   request.ConfigID,
		"config.Name": request.Spec.Annotations.Name,
		"method":      "UpdateConfig",
	}).Debugf("config updated")

	return &api.UpdateConfigResponse{
		Config: config,
	}, nil
}

// ListConfigs returns a `ListConfigResponse` with a list all non-internal `Config`s being
// managed, or all configs matching any name in `ListConfigsRequest.Names`, any
// name prefix in `ListConfigsRequest.NamePrefixes`, any id in
// `ListConfigsRequest.ConfigIDs`, or any id prefix in `ListConfigsRequest.IDPrefixes`.
// - Returns an error if listing fails.
func (s *Server) ListConfigs(_ context.Context, request *api.ListConfigsRequest) (*api.ListConfigsResponse, error) {
	var (
		configs     []*api.Config
		respConfigs []*api.Config
		err         error
		byFilters   []store.By
		by          store.By
		labels      map[string]string
	)

	// return all configs that match either any of the names or any of the name prefixes (why would you give both?)
	if request.Filters != nil {
		for _, name := range request.Filters.Names {
			byFilters = append(byFilters, store.ByName(name))
		}
		for _, prefix := range request.Filters.NamePrefixes {
			byFilters = append(byFilters, store.ByNamePrefix(prefix))
		}
		for _, prefix := range request.Filters.IDPrefixes {
			byFilters = append(byFilters, store.ByIDPrefix(prefix))
		}
		labels = request.Filters.Labels
	}

	switch len(byFilters) {
	case 0:
		by = store.All
	case 1:
		by = byFilters[0]
	default:
		by = store.Or(byFilters...)
	}

	s.store.View(func(tx store.ReadTx) {
		configs, err = store.FindConfigs(tx, by)
	})
	if err != nil {
		return nil, err
	}

	// filter by label
	for _, config := range configs {
		if !filterMatchLabels(config.Spec.Annotations.Labels, labels) {
			continue
		}
		respConfigs = append(respConfigs, config)
	}

	return &api.ListConfigsResponse{Configs: respConfigs}, nil
}

// CreateConfig creates and returns a `CreateConfigResponse` with a `Config` based
// on the provided `CreateConfigRequest.ConfigSpec`.
//   - Returns `InvalidArgument` if the `CreateConfigRequest.ConfigSpec` is malformed,
//     or if the config data is too long or contains invalid characters.
//   - Returns an error if the creation fails.
func (s *Server) CreateConfig(ctx context.Context, request *api.CreateConfigRequest) (*api.CreateConfigResponse, error) {
	if err := validateConfigSpec(request.Spec); err != nil {
		return nil, err
	}

	config := configFromConfigSpec(request.Spec) // the store will handle name conflicts
	err := s.store.Update(func(tx store.Tx) error {
		return store.CreateConfig(tx, config)
	})

	switch err {
	case store.ErrNameConflict:
		return nil, status.Errorf(codes.AlreadyExists, "config %s already exists", request.Spec.Annotations.Name)
	case nil:
		log.G(ctx).WithFields(log.Fields{
			"config.Name": request.Spec.Annotations.Name,
			"method":      "CreateConfig",
		}).Debugf("config created")

		return &api.CreateConfigResponse{Config: config}, nil
	default:
		return nil, err
	}

func (s *Server) GetService(_ context.Context, request *api.GetServiceRequest) (*api.GetServiceResponse, error) {
	if request.ServiceID == "" {
		return nil, status.Error(codes.InvalidArgument, errInvalidArgument.Error())
	}

	var service *api.Service
	s.store.View(func(tx store.ReadTx) {
		service = store.GetService(tx, request.ServiceID)
	})
	if service == nil {
		return nil, status.Errorf(codes.NotFound, "service %s not found", request.ServiceID)
	}

	if request.InsertDefaults {
		service.Spec = *defaults.InterpolateService(&service.Spec)
	}

	return &api.GetServiceResponse{
		Service: service,
	}, nil
}

// UpdateService updates a Service referenced by ServiceID with the given ServiceSpec.
// - Returns `NotFound` if the Service is not found.
// - Returns `InvalidArgument` if the ServiceSpec is malformed.
// - Returns `Unimplemented` if the ServiceSpec references unimplemented features.
// - Returns an error if the update fails.
func (s *Server) UpdateService(_ context.Context, request *api.UpdateServiceRequest) (*api.UpdateServiceResponse, error) {
	if request.ServiceID == "" || request.ServiceVersion == nil {
		return nil, status.Error(codes.InvalidArgument, errInvalidArgument.Error())
	}
	if err := validateServiceSpec(request.Spec); err != nil {
		return nil, err
	}

	if err := s.validateNetworks(request.Spec.Task.Networks); err != nil {
		return nil, err
	}

	var service *api.Service
	s.store.View(func(tx store.ReadTx) {
		service = store.GetService(tx, request.ServiceID)
	})
	if service == nil {
		return nil, status.Errorf(codes.NotFound, "service %s not found", request.ServiceID)
	}

	if request.Spec.Endpoint != nil && !reflect.DeepEqual(request.Spec.Endpoint, service.Spec.Endpoint) {
		if err := s.checkPortConflicts(request.Spec, request.ServiceID); err != nil {
			return nil, err
		}
	}

	err := s.store.Update(func(tx store.Tx) error {
		service = store.GetService(tx, request.ServiceID)
		if service == nil {
			return status.Errorf(codes.NotFound, "service %s not found", request.ServiceID)
		}

		// It's not okay to update Service.Spec.Networks on its own.
		// However, if Service.Spec.Task.Networks is also being
		// updated, that's okay (for example when migrating from the
		// deprecated Spec.Networks field to Spec.Task.Networks).
		if (len(request.Spec.Networks) != 0 || len(service.Spec.Networks) != 0) &&
			!reflect.DeepEqual(request.Spec.Networks, service.Spec.Networks) &&
			reflect.DeepEqual(request.Spec.Task.Networks, service.Spec.Task.Networks) {
			return status.Error(codes.Unimplemented, errNetworkUpdateNotSupported.Error())
		}

		// Check to see if all the secrets being added exist as objects
		// in our datastore
		err := s.checkSecretExistence(tx, request.Spec)
		if err != nil {
			return err
		}

		err = s.checkConfigExistence(tx, request.Spec)
		if err != nil {
			return err
		}

		// orchestrator is designed to be stateless, so it should not deal
		// with service mode change (comparing current config with previous config).
		// proper way to change service mode is to delete and re-add.
		if reflect.TypeOf(service.Spec.Mode) != reflect.TypeOf(request.Spec.Mode) {
			return status.Error(codes.Unimplemented, errModeChangeNotAllowed.Error())
		}

		if service.Spec.Annotations.Name != request.Spec.Annotations.Name {
			return status.Error(codes.Unimplemented, errRenameNotSupported.Error())
		}

		service.Meta.Version = *request.ServiceVersion

		// if the service has a JobStatus, that means it must be a Job, and we
		// should increment the JobIteration
		if service.JobStatus != nil {
			service.JobStatus.JobIteration.Index = service.JobStatus.JobIteration.Index + 1
			service.JobStatus.LastExecution = gogotypes.TimestampNow()
		}

		if request.Rollback == api.UpdateServiceRequest_PREVIOUS {
			if service.PreviousSpec == nil {
				return status.Errorf(codes.FailedPrecondition, "service %s does not have a previous spec", request.ServiceID)
			}

			curSpec := service.Spec.Copy()
			curSpecVersion := service.SpecVersion
			service.Spec = *service.PreviousSpec.Copy()
			service.SpecVersion = service.PreviousSpecVersion.Copy()
			service.PreviousSpec = curSpec
			service.PreviousSpecVersion = curSpecVersion

			service.UpdateStatus = &api.UpdateStatus{
				State:     api.UpdateStatus_ROLLBACK_STARTED,
				Message:   "manually requested rollback",
				StartedAt: ptypes.MustTimestampProto(time.Now()),
			}
		} else {
			service.PreviousSpec = service.Spec.Copy()
			service.PreviousSpecVersion = service.SpecVersion
			service.Spec = *request.Spec.Copy()
			// Set spec version. Note that this will not match the
			// service's Meta.Version after the store update. The
			// versions for the spec and the service itself are not
			// meant to be directly comparable.
			service.SpecVersion = service.Meta.Version.Copy()

			// Reset update status
			service.UpdateStatus = nil
		}

		if allocator.IsIngressNetworkNeeded(service) {
			if _, err := allocator.GetIngressNetwork(s.store); err == allocator.ErrNoIngress {
				return status.Errorf(codes.FailedPrecondition, "service needs ingress network, but no ingress network is present")
			}
		}

		return store.UpdateService(tx, service)
	})
	if err != nil {
		return nil, err
	}

	return &api.UpdateServiceResponse{
		Service: service,
	}, nil
}

