func NewMemoryStore(proposer state.Proposer) *MemoryStore {
	memDB, err := memdb.NewMemDB(schema)
	if err != nil {
		// This shouldn't fail
		panic(err)
	}

	return &MemoryStore{
		memDB:    memDB,
		queue:    watch.NewQueue(),
		proposer: proposer,
	}
}

func (s *MemoryStore) View(cb func(ReadTx)) {
	defer metrics.StartTimer(viewLatencyTimer)()
	memDBTx := s.memDB.Txn(false)

	readTx := readTx{
		memDBTx: memDBTx,
	}
	cb(readTx)
	memDBTx.Commit()
}

}

func (s *MemoryStore) updateAt(proposer state.Proposer, appliedVersion *api.Version, cb func(Tx) error) error {
	defer metrics.StartTimer(updateLatencyTimer)()
	s.updateLock.Lock()
	memDBTx := s.memDB.Txn(true)

	var curVersion *api.Version

	if proposer != nil {
		curVersion = proposer.GetVersion()
	}

	var tx tx
	tx.init(memDBTx, curVersion)

	err := cb(&tx)

	commitGuard := make(chan struct{}, 1)
	commitGuard <- struct{}{}

	if err == nil {
		if proposer == nil {
			memDBTx.Commit()
			if len(tx.changelist) != 0 || appliedVersion != nil {
				s.appliedVersion = appliedVersion.Copy()
			}
		} else {
			var sa []api.StoreAction
			sa, err = tx.changelistStoreActions()

			if err == nil {
				if len(sa) != 0 {
					err = proposeAt(proposer, sa, func(version *api.Version) {
						select {
						case <-commitGuard:
							memDBTx.Commit()
							s.appliedVersion = version.Copy()
						default:
							// Already Abort()ed.
						}
					})
				} else {
					memDBTx.Commit()
				}
			}
		}
	}

	if err == nil {
		for _, c := range tx.changelist {
			s.queue.Publish(c)
		}
		if len(tx.changelist) != 0 {
			s.queue.Publish(state.EventCommit{Version: s.appliedVersion.Copy()})
		}
	} else {
		// The ProposeValue callback could still have executed, or be
		// executed in the near future. Guard against racing the
		// Commit().
		select {
		case <-commitGuard:
			memDBTx.Abort()
		default:
			// Already Abort()ed.
		}
	}
	s.updateLock.Unlock()
	return err
}

func (s *MemoryStore) updateLocal(cb func(Tx) error) error {
	return s.update(nil, cb)
}

// Update executes a read/write transaction.
func (s *MemoryStore) Update(cb func(Tx) error) error {
	return s.update(s.proposer, cb)

