func reserveControllerPorts(t *testing.T, count int) []int {
	t.Helper()
	listeners := make([]net.Listener, 0, count)
	defer func() {
		for _, listener := range listeners {
			if err := listener.Close(); err != nil {
				t.Errorf("close reserved controller port: %v", err)
			}
		}
	}()
	ports := make([]int, count)
	for index := range ports {
		listener, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatal(err)
		}
		listeners = append(listeners, listener)
		ports[index] = listener.Addr().(*net.TCPAddr).Port
	}
	return ports
}

func startControllerChild(t *testing.T, ctx context.Context, root, config string, boot, index int) *controllerChild {
	t.Helper()
	executable, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	logPath := filepath.Join(root, fmt.Sprintf("boot%d-peer%d.log", boot, index))
	logFile, err := os.Create(logPath)
	if err != nil {
		t.Fatal(err)
	}
	cmd := exec.CommandContext(ctx, executable, "-test.run=^TestControllerThreeProcessBootstrapAndRestart$")
	cmd.Env = append(os.Environ(), "TS_ORCH_TEST_CONTROLLER_CHILD_CONFIG="+config)
	cmd.Stdout, cmd.Stderr = logFile, logFile
	if err := cmd.Start(); err != nil {
		logFile.Close()
		t.Fatal(err)
	}
	child := &controllerChild{cmd: cmd, done: make(chan struct{}), logPath: logPath, started: time.Now()}
	go func() {
		child.err = cmd.Wait()
		logFile.Close()
		close(child.done)
	}()
	t.Cleanup(func() {
		select {
		case <-child.done:
			return
		default:
		}
		_ = cmd.Process.Kill()
		// Reap even failed fixtures before the next lab test starts. Reading
		// Cmd.ProcessState while Wait writes it also races under -race.
		select {
		case <-child.done:
		case <-time.After(controllerStopBudget):
			t.Errorf("controller cleanup did not reap child: %s", child.logPath)
		}
	})
	return child
}

func assertControllerChildRunning(t *testing.T, child *controllerChild) {
	t.Helper()
	select {
	case <-child.done:
		data, _ := os.ReadFile(child.logPath)
		t.Fatalf("controller exited before quorum: %v; log %s\n%s", child.err, child.logPath, data)
	default:
	}
}

func waitControllerChildReady(t *testing.T, ctx context.Context, child *controllerChild) {
	t.Helper()
	ctx, cancel := context.WithDeadline(ctx, child.started.Add(controllerStartupBudget(t)))
	defer cancel()
	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	for {
		assertControllerChildRunning(t, child)
		data, _ := os.ReadFile(child.logPath)
		if strings.Contains(string(data), " ready in cell ") {
			return
		}
		select {
		case <-ctx.Done():
			t.Fatalf("controller readiness: %v; log %s\n%s", ctx.Err(), child.logPath, data)
		case <-ticker.C:
		}
	}
}

// The founder is deliberately absent here. Wait for both listeners instead
// of assuming that a three-second sleep lets the other processes start.
func waitControllerChildListening(t *testing.T, ctx context.Context, child *controllerChild, ports ...int) {
	t.Helper()
	ctx, cancel := context.WithDeadline(ctx, child.started.Add(controllerStartupBudget(t)))
	defer cancel()
	var lastErr error
	for ctx.Err() == nil {
		assertControllerChildRunning(t, child)
		listening := true
		for _, port := range ports {
			conn, err := (&net.Dialer{Timeout: 100 * time.Millisecond}).DialContext(ctx, "tcp", fmt.Sprintf("127.0.0.1:%d", port))
			if err != nil {
				lastErr, listening = err, false
				break
			}
			conn.Close()
		}
		if listening {
			assertControllerChildRunning(t, child)
			return
		}
		select {
		case <-ctx.Done():
		case <-time.After(50 * time.Millisecond):
		}
	}
	data, _ := os.ReadFile(child.logPath)
	t.Fatalf("controller listeners: %v; last error %v; log %s\n%s", ctx.Err(), lastErr, child.logPath, data)
}

func controllerStartupBudget(t *testing.T) time.Duration {
	t.Helper()
	// Use the deployed bootstrap admission budget for forming a fresh lab
	// cell, including embedded NATS startup and provisioning retries.
	data, err := os.ReadFile("../../deploy/systemd/terrascale-orchestrator-bootstrap.service")
	if err != nil {
		t.Fatal(err)
	}
	for line := range strings.SplitSeq(string(data), "\n") {
		if value, ok := strings.CutPrefix(line, "TimeoutStartSec="); ok {
			budget, err := time.ParseDuration(value)
			if err != nil || budget <= 0 {
				t.Fatalf("invalid bootstrap startup budget %q: %v", value, err)
			}
			return budget
		}
	}
	t.Fatal("bootstrap unit has no startup budget")
	return 0
}

func stopControllerChild(t *testing.T, child *controllerChild) {
	t.Helper()
	signalControllerChild(t, child)
	waitControllerChildStopped(t, child)
}

func signalControllerChild(t *testing.T, child *controllerChild) {
	t.Helper()
	child.stopping = time.Now()
	if err := child.cmd.Process.Signal(syscall.SIGTERM); err != nil {
		data, _ := os.ReadFile(child.logPath)
		t.Fatalf("controller signal: %v; log %s\n%s", err, child.logPath, data)
	}
}

func crashControllerChild(t *testing.T, child *controllerChild) {
	t.Helper()
	if err := child.cmd.Process.Kill(); err != nil {
		t.Fatal(err)
	}
	select {
	case <-child.done:
	case <-time.After(10 * time.Second):
		t.Fatalf("crashed controller did not exit: %s", child.logPath)
	}
}

func waitSurvivingAuthority(t *testing.T, ctx context.Context, auth *authenticatedNATS, port int, priorEpoch uint64) {
	t.Helper()
	probeCtx, cancel := context.WithTimeout(ctx, 35*time.Second)
	defer cancel()
	probe, err := auth.start(t, probeCtx, natscell.Config{Cell: "lab", Instance: "failover-probe", Replicas: 3,
		URL: fmt.Sprintf("nats://127.0.0.1:%d", port)})
	if err != nil {
		t.Fatal(err)
	}
	defer probe.Close()
	var last authority.Snapshot
	var lastErr error
	for probeCtx.Err() == nil {
		attempt, stop := context.WithTimeout(probeCtx, 2*time.Second)
		last, lastErr = authority.Observe(attempt, probe.JetStream(), "lab")
		stop()
		if lastErr == nil && last.Ready && last.Epoch > priorEpoch {
			return
		}
		select {
		case <-probeCtx.Done():
		case <-time.After(250 * time.Millisecond):
		}
	}
	t.Fatalf("authority did not take over after leader crash: previous epoch=%d last=%+v err=%v", priorEpoch, last, lastErr)
}

// controllerStopBudget matches TimeoutStopSec in the controller unit. The
// last controller of a stopping cell has no JetStream quorum, so its graceful
// shutdown waits out in-flight request timeouts.
const controllerStopBudget = 60 * time.Second

func waitControllerChildStopped(t *testing.T, child *controllerChild) {
	t.Helper()
	select {
	case <-child.done:
		if child.err != nil {
			data, _ := os.ReadFile(child.logPath)
			t.Fatalf("controller shutdown: %v; log %s\n%s", child.err, child.logPath, data)
		}
	case <-time.After(time.Until(child.stopping.Add(controllerStopBudget))):
		data, _ := os.ReadFile(child.logPath)
		t.Fatalf("controller did not stop within %s: %s\n%s", controllerStopBudget, child.logPath, data)
	}
}

func controllerChildCandidateID(t *testing.T, child *controllerChild) string {
	t.Helper()
	data, err := os.ReadFile(child.logPath)
	if err != nil {
		t.Fatal(err)
	}
	for _, line := range strings.Split(string(data), "\n") {
		// Under journald each record starts with its syslog priority, such as <5>.
		if len(line) > 3 && line[0] == '<' && line[2] == '>' {
			line = line[3:]
		}
		var record struct {
			CandidateID string `json:"candidate_id"`
		}
		if json.Unmarshal([]byte(line), &record) == nil && entityid.Valid(record.CandidateID) {
			return record.CandidateID
		}
	}
	t.Fatalf("controller candidate identity missing from %s", child.logPath)
	return ""
}

func Run(ctx context.Context, args []string, output io.Writer) error {
	if len(args) == 0 {
		return errors.New("usage: terrascale-orchestrator <bootstrap-controller|run|host|check|operator|identity-new|netbird-enroll|netbird-agent> --config FILE")
	}
	command := args[0]
	if command == "runtime-worker-admission-source" {
		return runRuntimeWorkerAdmissionSource(ctx, args[1:], os.Stdin, output)
	}
	if command == runtimeControllerHostSourceCommand {
		return runRuntimeControllerHostAdmissionSource(ctx, args[1:], os.Stdin, output)
	}
	if command == "runtime-worker-membership-source" {
		return runRuntimeWorkerMembershipSource(ctx, args[1:], os.Stdin, output)
	}
	if command == runtimeRegistrySourceCommand {
		return runRuntimeRegistrySource(ctx, args[1:], os.Stdin, output)
	}
	if command == "netbird-agent" {
		return runNetBirdAgent(ctx, args[1:])
	}
	if command == "bootstrap-credential-check" {
		if len(args) != 1 {
			return errors.New("bootstrap credential check accepts no arguments")
		}
		return bootstrapstart.RunCredentialValidationChild(os.Stdin, func(request bootstrapstart.CredentialChildRequest) error {
			if _, err := readPrivateKey(request.ResponseKeyFile); err != nil {
				return fmt.Errorf("controller response key: %w", err)
			}
			cfg := Config{NATS: request.Config, Controller: ControllerConfig{BrokerTicketKeyFile: request.BrokerTicketKeyFile}}
			_, _, err := brokerTicketKeys(cfg)
			return err
		})
	}
	if command == "bootstrap-admit-initial" || command == "bootstrap-admit-restart" {
		if len(args) != 1 {
			return errors.New("bootstrap admission child accepts no arguments")
		}
		return runControllerAdmissionChild(ctx, command, os.Stdin)
	}
	if command == "identity-new" {
		return newIdentity(args[1:], output)
	}
	if command == "netbird-enroll" {
		return runNetBirdEnroll(ctx, args[1:], output)
	}
	if command == "install-controller-config" {
		return runInstallControllerConfig(ctx, args[1:])
	}
	if command == "identity-rekey" {
		return runIdentityRekey(ctx, args[1:], output)
	}
	if command == "host-setup" {
		return runHostSetup(ctx, args[1:], output)
	}
	if command == "restore-controller-material" {
		return runRestoreControllerMaterial(ctx, args[1:], output)
	}
	if command == "host-volume-init" {
		return runHostVolumeInit(ctx, args[1:])
	}
	if command == "operator" {
		return runOperator(ctx, args[1:], output)
	}
	if command == "service" {
		return runService(ctx, args[1:], output)
	}
	if command == "get" || command == "diff" || command == "apply" {
		return runSpec(ctx, command, args[1:], output)
	}
	if command == "rollout" {
		return runRollout(ctx, args[1:], output)
	}
	if command == "node" {
		return runNode(ctx, args[1:], output)
	}
	flags := flag.NewFlagSet(command, flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	configPath := flags.String("config", "", "JSON role configuration")
	if err := flags.Parse(args[1:]); err != nil {
		return err
	}
	if flags.NArg() != 0 {
		return fmt.Errorf("%s does not accept positional arguments", command)
	}
	cfg, err := LoadConfig(*configPath)
	if err != nil {
		return err
	}
	switch command {
	case "bootstrap-controller":
		return controllerBootstrapCommand(ctx, cfg)
	case "run":
		return runController(ctx, cfg, output)
	case "host":
		return runHost(ctx, cfg, *configPath, output)
	case "check":
		return check(ctx, cfg, output)
	case "identity-rekey-completion-check":
		return checkControllerIdentityRekeyCompletion(ctx, cfg)
	default:
		return fmt.Errorf("unknown command %q", command)
	}
}

func runController(ctx context.Context, cfg Config, output io.Writer) (err error) {
	// Take the systemd notification socket before any child process starts.
	notifier := sdnotify.FromEnvironment()
	defer func() { _ = notifier.Stopping() }()
	telemetry, err := startRuntimeObservability(ctx, cfg, "controller", cfg.NATS.Instance)
	if err != nil {
		return fmt.Errorf("start controller observability: %w", err)
	}
	defer telemetry.close()
	clockProbe := controllerBrokerClockProbe()
	clockCheck := controllerClockCheck(clockProbe)
	admission, err := startControllerAdmission(ctx, cfg, clockCheck)
	if err != nil {
		return err
	}
	defer admission.stop()
	if cfg.NATS.Embedded == nil {
		return errors.New("controller run requires an embedded regional NATS server")
	}
	artifactStoreMaxBytes := cfg.Controller.ArtifactStoreMaxBytes
	if artifactStoreMaxBytes < 0 {
		return errors.New("controller artifact_store_max_bytes must be positive when set")
	}
	if artifactStoreMaxBytes == 0 {
		artifactStoreMaxBytes = delivery.DefaultArtifactStoreMaxBytes
	}
	storeLimitBytes := cfg.NATS.Embedded.StoreLimitBytes()
	if storeLimitBytes < artifactStoreMaxBytes || storeLimitBytes-artifactStoreMaxBytes < controlStoreHeadroomBytes {
		return fmt.Errorf("embedded NATS store_max_bytes must leave at least %d bytes for control state beyond artifact_store_max_bytes", controlStoreHeadroomBytes)
	}
	managed, err := loadManagedControllerConfig(cfg)
	if err != nil {
		return err
	}

if !admission.offline {
	if err := clockCheck(); err != nil {
		return fmt.Errorf("production broker NTP clock health: %w", err)
	}
}

cfg.NATS.ClientRole = "controller"
runtime, err := controllerRuntimeProduction(ctx, cfg, clockCheck)
if err != nil {
