var statefulServices statefulRuntimeSlot
planner := &regionalDeliveryPlanner{profiles: services.profiles, address: services.nodeAddress, migrated: func(role string) bool { return role != terrabase.Role }}
service, _, err := retryControllerOpen(ctx, "open regional delivery stores", fullClusterReady, false,
	func(attempt context.Context) (*delivery.Service, error) {
		return delivery.Open(attempt, delivery.Config{
			Conn: runtime.Conn(), JS: runtime.JetStream(), Cell: cfg.NATS.Cell, Replicas: cfg.NATS.Replicas,
			ArtifactStoreMaxBytes: artifactStoreMaxBytes,

func Start(ctx context.Context, js jetstream.JetStream, config Config) (*Runtime, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	config = config.withDefaults()
	if err := config.validate(); err != nil {
		return nil, err
	}
	if config.ClockCheck != nil && config.ClockCheck() != nil {
		return nil, ErrClockUnhealthy
	}
	logger := config.Logger
	if logger == nil {
		logger = slog.Default()
	}
	stream, err := openControlStream(ctx, js, config.Replicas)
	if err != nil {
		return nil, fmt.Errorf("open authority control log: %w", err)
	}
	readCtx, readCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readStream, err := js.Stream(readCtx, ControlStreamName)
	readCancel()
	if err != nil {
		return nil, fmt.Errorf("open authority read handle: %w", err)
	}
	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readInfo, err := readStream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return nil, fmt.Errorf("inspect authority read handle: %w", err)
	}
	if err := verifyControlStreamConfig(readInfo.Config, config.Replicas); err != nil {
		return nil, fmt.Errorf("validate authority read handle: %w", err)
	}
	loopCtx, cancel := context.WithCancel(ctx)
	runtime := &Runtime{
		js:          js,
		publisher:   js,
		stream:      stream,
		readStream:  readStream,
		config:      config,
		leaseSub:    fmt.Sprintf("%s.%s.lease", controlSubjectRoot, config.Scope),
		ownerID:     entityid.New(),
		logger:      logger,
		diagnostics: authorityDiagnosticQueue,
		diagTimes:   make(map[string]time.Time),
		cancel:      cancel,
		done:        make(chan struct{}),
	}
	runtime.publishSnapshot(Snapshot{Scope: config.Scope, DeploymentID: config.DeploymentID, CandidateID: config.CandidateID, OwnerID: runtime.ownerID, Reason: "not-observed"})
	runtime.logSnapshotTransition()
	var observeErr error
	for attempt := range startupReconcileAttempts {
		observeErr = runtime.reconcileWithRetry(loopCtx)
		runtime.logSnapshotTransition()
		if observeErr != nil && loopCtx.Err() != nil {
			observeErr = loopCtx.Err()
			break
		}
		if observeErr == nil || !retryableStartupReconcileError(loopCtx, observeErr) || attempt+1 == startupReconcileAttempts {
			break
		}
		timer := time.NewTimer(startupReconcileDelay(attempt, observeErr))
		select {
		case <-loopCtx.Done():
			observeErr = loopCtx.Err()
			timer.Stop()
		case <-timer.C:
		}
	}
	if observeErr != nil {
		cancel()
		close(runtime.done)
		return nil, fmt.Errorf("observe authority lease: %w", observeErr)
	}
	go runtime.run(loopCtx)
	return runtime, nil
}

func Observe(ctx context.Context, js jetstream.JetStream, scope string) (Snapshot, error) {
	if js == nil {
		return Snapshot{}, errors.New("JetStream is required")
	}
	if !natsToken.MatchString(scope) {
		return Snapshot{}, errors.New("authority scope must be a lowercase NATS token")
	}
	stream, err := js.Stream(ctx, ControlStreamName)
	if err != nil {
		return Snapshot{}, err
	}
	subject := fmt.Sprintf("%s.%s.lease", controlSubjectRoot, scope)
	for range 8 {
		info, err := stream.Info(ctx)
		if err != nil {
			return Snapshot{}, err
		}
		if err := verifyControlStreamConfig(info.Config, info.Config.Replicas); err != nil {
			return Snapshot{}, err
		}
		entry, err := stream.GetLastMsgForSubject(ctx, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			return Snapshot{Scope: scope, Ready: true, ObservedAt: time.Now(), Reason: "no-lease"}, nil
		}
		if err != nil {
			return Snapshot{}, err
		}
		if entry.Sequence > info.State.LastSeq {
			continue
		}
		lease, err := decodeLease(entry.Data)
		if err != nil || lease.Scope != scope {
			return Snapshot{Scope: scope, Revision: entry.Sequence, ObservedAt: time.Now(), Reason: "lease-corrupt"}, ErrLeaseCorrupt
		}
		expiresAt := entry.Time.Add(time.Duration(lease.LeaseDuration))
		now := time.Now()
		snapshot := Snapshot{
			Scope: scope, DeploymentID: lease.DeploymentID, CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Ready: true, Epoch: lease.Epoch,
			Revision: entry.Sequence, ExpiresAt: expiresAt, ObservedAt: now, Reason: "observed",
		}
		if lease.Released || !now.Before(expiresAt) {
			snapshot.Ready = false
			snapshot.Reason = "lease-inactive"
		}
		return snapshot, nil
	}
	return Snapshot{}, ErrConflict
}

